discrete PowerManagementSystem
port:
    event input real Start;
    event input real Stop;
    event input real FaultCleared;
    event output real PowerSupply;
    event output real FaultHandling;
state:
    initial state Initial
        when entry() then
            statehold(0);
        end;
        when receive(Start) then
            transition(PowerSupply);
        end;
    end;

    state PowerSupply
        when entry() then
            statehold(0);
        end;
        when receive(FaultCleared) then
            transition(PowerSupply);
        end;
        when receive(Stop) then
            transition(Initial);
        end;
        when receive(PowerFault) then
            transition(FaultHandling);
        end;
    end;

    state FaultHandling
        when entry() then
            statehold(30); // Ongoing30Seconds are not broken.
end;
        when timeover() then
            transition(Initial);
        end;
        when receive(FaultCleared) then
            transition(PowerSupply);
        end;
    end;
end;
end;

discrete ReferenceVoltageGenerationSystem
port:
    event input real PowerOn;
    event input real PowerOff;
    event input real VoltageStable;
    event input real FaultCleared;
    event output real StableVoltageOutput;
    event output real VoltageAdjustment;
    event output real FaultAlarm;
state:
    initial state Initial
        when entry() then
            statehold(0);
        end;
        when receive(PowerOn) then
            transition(StableVoltageOutput);
        end;
    end;

    state StableVoltageOutput
        when entry() then
            statehold(0);
        end;
        when receive(VoltageStable) then
            transition(StableVoltageOutput);
        end;
        when receive(VoltageFluctuation) then
            transition(VoltageAdjustment);
        end;
        when receive(PowerOff) then
            transition(Initial);
        end;
    end;

    state VoltageAdjustment
        when entry() then
            statehold(0);
        end;
        when receive(VoltageStable) then
            transition(StableVoltageOutput);
        end;
        when receive(AdjustmentFailed) then
            transition(FaultAlarm);
        end;
    end;

    state FaultAlarm
        when entry() then
            statehold(30); // Ongoing30Seconds are not broken.
end;
        when timeover() then
            transition(Initial);
        end;
        when receive(FaultCleared) then
            transition(StableVoltageOutput);
        end;
    end;
end;
end;

discrete MonitoringAndControlSystem
port:
    event input real SystemReady;
    event input real Shutdown;
    event input real AnomalyResolved;
    event output real NormalMonitoring;
    event output real AnomalyHandling;
state:
    initial state Initial
        when entry() then
            statehold(0);
        end;
        when receive(SystemReady) then
            transition(NormalMonitoring);
        end;
    end;

    state NormalMonitoring
        when entry() then
            statehold(0);
        end;
        when receive(AnomalyDetected) then
            transition(AnomalyHandling);
        end;
        when receive(Shutdown) then
            transition(Initial);
        end;
    end;

    state AnomalyHandling
        when entry() then
            statehold(30); // Ongoing30The second hasn&#x27;t handled the anomaly.
end;
        when timeover() then
            transition(Initial);
        end;
        when receive(AnomalyResolved) then
            transition(NormalMonitoring);
        end;
    end;
end;
end;

couple PowerSystem
import architectureModels.PowerManagementSystem as PMS;
import architectureModels.ReferenceVoltageGenerationSystem as RVGS;
import architectureModels.MonitoringAndControlSystem as MCS;
part:
    PMS pmsInstance;
    RVGS rvgsInstance;
    MCS mcsInstance;
connection:
    connect(pmsInstance.PowerSupply, rvgsInstance.PowerOn);
    connect(pmsInstance.PowerSupply, mcsInstance.SystemReady);
    connect(rvgsInstance.StableVoltageOutput, mcsInstance.VoltageInput);
    connect(mcsInstance.FaultDetected, rvgsInstance.FaultInput);
    connect(rvgsInstance.FaultOutput, pmsInstance.FaultCleared);
    connect(mcsInstance.ShutdownOutput, pmsInstance.Stop);
end;
